import{_ as n,o as t,c as r,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Lernabschnitte und Leistungen verwalten","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/lernabschnitte.md","filePath":"schild3/lernabschnitte.md"}'),i={name:"schild3/lernabschnitte.md"};function s(h,e,l,u,c,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="lernabschnitte-und-leistungen-verwalten" tabindex="-1">Lernabschnitte und Leistungen verwalten <a class="header-anchor" href="#lernabschnitte-und-leistungen-verwalten" aria-label="Permalink to &quot;Lernabschnitte und Leistungen verwalten&quot;">​</a></h1><p>Klassen, Unterricht und Leistungen gehören zu einem bestimmten Lernabschnitt. Prüfen Sie deshalb zuerst Schuljahr und Abschnitt, bevor Sie Daten ändern.</p><h2 id="den-richtigen-abschnitt-wahlen" tabindex="-1">Den richtigen Abschnitt wählen <a class="header-anchor" href="#den-richtigen-abschnitt-wahlen" aria-label="Permalink to &quot;Den richtigen Abschnitt wählen&quot;">​</a></h2><p>Die Anleitung <a href="/schild3/schueler/aktuelles-halbjahr-aktueller-abschnitt-schueler.html">Lernabschnitte und aktuelle Laufbahndaten verwalten</a> erläutert die Abschnittsübersicht, Wertung, Wiederholung und die zugehörigen Laufbahndaten. Für den Wechsel in ein neues Halbjahr oder Schuljahr verwenden Sie <a href="/zeugnisse/versetzung.html">Versetzung und Abschnittswechsel</a>.</p><h2 id="unterricht-und-leistungen-pflegen" tabindex="-1">Unterricht und Leistungen pflegen <a class="header-anchor" href="#unterricht-und-leistungen-pflegen" aria-label="Permalink to &quot;Unterricht und Leistungen pflegen&quot;">​</a></h2><ul><li><a href="/schild3/schueler/leistungsdaten-aktuelles-halbjahr-aktueller-abschnitt.html">Fächer, Kurse und Leistungsdaten bearbeiten</a>: Fachbelegungen, Kurse und Noten im gewählten Abschnitt bearbeiten.</li><li><a href="/schild3/schueler/fehlzeiten-aktuelles-halbjahr-aktueller-abschnitt.html">Fehlzeiten tagesbezogen erfassen und auswerten</a>: tagesbezogene Fehlzeiten erfassen und auswerten.</li><li><a href="/schild3/schueler/laufbahninfo-schueler.html">Sprachenfolge, Prüfungen und Abschlüsse dokumentieren</a>: Sprachenfolge, Sprachprüfungen und erreichte Abschlüsse nachschlagen.</li><li><a href="/schild3/schueler/uebersicht-schueler.html">Leistungen über mehrere Lernabschnitte vergleichen</a>: den Leistungsstand mehrerer Abschnitte vergleichen.</li></ul><p>Für die gemeinsame Noteneingabe und die Vorbereitung des Ausdrucks wechseln Sie zu <a href="/zeugnisse/vorbereitung.html">Zeugnisse vorbereiten</a>. Die <a href="/schild3/faecher-kurse.html">Unterrichtszuweisung für Schülergruppen</a> ist separat beschrieben.</p>',7)])])}const o=n(i,[["render",s]]);export{g as __pageData,o as default};
